parameters.query:
select config->'youtube_discovery_queries' as queries, id as segment_id
from segments
where slug = 'us-production-houses';

parameters.jsCode:
// Node: Split Queries  |  Mode: Run Once for All Items
// Runs right after the Postgres "Load Config" node.
// Input: 1 item —
//   { queries: [ { query, genre_hint }, ... ], segment_id: "<uuid>" }
// Output: one item per discovery query, each carrying segment_id
// forward so every later item can reach it without a lookup.

const row = $input.first().json;
const queries = row.queries || [];
const segmentId = row.segment_id;

return queries.map(q => ({
  json: {
    query: q.query,
    genre_hint: q.genre_hint !== undefined ? q.genre_hint : null,
    segment_id: segmentId
  }
}));

// Node: Flatten Search Results  |  Mode: Run Once for All Items
// Runs after the HTTP Request node that calls YouTube search.list once
// per item from "Split Queries".
//
// Input: one item PER QUERY, each holding a raw search.list response
// (up to 25 channels nested in .items[]).
//
// IMPORTANT ASSUMPTION: this zips search responses to their original
// query by ARRAY INDEX against $('Split Queries').all(). n8n runs the
// HTTP Request node once per input item, in the same order, so this
// pairing is reliable as long as no node in between reorders or drops
// items. This is the part most likely to need a look if results come
// back attached to the wrong query on first real test.
//
// Output: one item per unique channel (deduped within this run),
// carrying the query context forward.

const queryItems = $('Split Queries').all();
const searchResponses = $input.all();

const seen = new Set();
const output = [];

searchResponses.forEach((resp, idx) => {
  const ctx = queryItems[idx] ? queryItems[idx].json : {};
  const channels = (resp.json && resp.json.items) || [];

  for (const ch of channels) {
    const channelId = ch.id && ch.id.channelId;
    if (!channelId || seen.has(channelId)) continue;
    seen.add(channelId);

    output.push({
      json: {
        channel_id: channelId,
        matched_query: ctx.query || null,
        genre_hint: ctx.genre_hint !== undefined ? ctx.genre_hint : null,
        segment_id: ctx.segment_id || null
      }
    });
  }
});

return output;

// Node: Filter, Score, and Shape for Staging  |  Mode: Run Once for All Items
// Runs after the HTTP Request node that calls YouTube channels.list once
// per item from "Flatten Search Results" (one channel_id per call — not
// batched into groups of 50, a deliberate v1 simplification: channels.list
// costs only 1 quota unit/call, so even ~150 individual calls is trivial
// against the 10,000/day budget, and skipping batching removes a whole
// layer of item-grouping logic that would otherwise be unverified until
// a live test run).
//
// THRESHOLDS BELOW ARE A STARTING POINT, NOT FINAL - tune them during
// S3.8's real-query test against actual results.
//
// KNOWN v1 SIMPLIFICATION: this connector does NOT set activity_signal
// (the is_active gate's input). A real "last upload" check needs a
// separate API call this script doesn't make. Leaving the key unset is
// SAFE by design - the gate treats unknown as pass-through - it just
// means the is_active gate won't actively catch anything yet from this
// connector; Layer B enrichment (which visits the real site) is a more
// natural place to add a fuller check later.

const ADMIT_KEYWORDS = ['studio', 'media', 'production', 'productions', 'network', 'films', 'pictures', 'entertainment'];
const SUBSCRIBER_FLOOR = 1000;
const OVERSIZED_SUBSCRIBER_CEILING = 5000000;
const KNOWN_MAJORS_KEYWORDS = [
  'disney', 'warner bros', 'nbcuniversal', 'paramount', 'sony pictures',
  'viacomcbs', 'mgm', 'lionsgate', 'netflix', 'amazon studios', 'hbo',
  'a24', 'universal pictures', '20th century'
];

function extractDomain(text) {
  if (!text) return null;
  const urlRegex = /https?:\/\/(?:www\.)?([a-z0-9-]+(?:\.[a-z0-9-]+)+)(?:\/[^\s]*)?/gi;
  const matches = [...text.matchAll(urlRegex)];
  const EXCLUDE = ['youtube.com', 'youtu.be', 'instagram.com', 'twitter.com', 'x.com',
                   'facebook.com', 'tiktok.com', 'linkedin.com', 'linktr.ee', 'bit.ly'];
  for (const m of matches) {
    const host = m[1].toLowerCase();
    if (!EXCLUDE.some(ex => host === ex || host.endsWith('.' + ex))) {
      return host;
    }
  }
  return null;
}

function extractEmail(text) {
  if (!text) return null;
  const emailRegex = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;
  const direct = text.match(emailRegex);
  if (direct) return direct[0].toLowerCase();
  const deobfuscated = text
    .replace(/\s*\[?\(?\s*at\s*\)?\]?\s*/gi, '@')
    .replace(/\s*\[?\(?\s*dot\s*\)?\]?\s*/gi, '.');
  const fallback = deobfuscated.match(emailRegex);
  return fallback ? fallback[0].toLowerCase() : null;
}

const channelItems = $('Flatten Search Results').all();
const detailResponses = $input.all();

const output = [];

detailResponses.forEach((resp, idx) => {
  const ctx = channelItems[idx] ? channelItems[idx].json : {};
  const channel = resp.json && resp.json.items && resp.json.items[0];
  if (!channel) return; // channels.list found nothing for this id - skip

  const snippet = channel.snippet || {};
  const stats = channel.statistics || {};
  const title = snippet.title || '';
  const description = snippet.description || '';
  const subscriberCount = stats.subscriberCount ? parseInt(stats.subscriberCount, 10) : null;
  const country = snippet.country || null;

  // --- ADMISSION FILTER: creators-vs-studios judgment ---
  const haystack = (title + ' ' + description).toLowerCase();
  const keywordHit = ADMIT_KEYWORDS.some(k => haystack.includes(k));
  const aboveFloor = subscriberCount !== null && subscriberCount >= SUBSCRIBER_FLOOR;
  if (!keywordHit && !aboveFloor) {
    return; // discarded - neither signal suggests a real studio
  }

  // --- scoring_inputs this connector can set (null-vs-zero rule: only
  // write a key when there's real evidence either way; leave it out
  // entirely if genuinely unassessed) ---
  const scoringInputs = {};

  // genre_fit: HALF credit, never full. Changed 2026-08-23, after the fixture
  // run showed this awarding a full 15/15 to every channel a genre-flavoured
  // query happened to surface -- Netflix included.
  //
  // All we actually know is that YouTube relevance-matched the channel to a
  // string like "workplace comedy channel". That is real evidence, but weak:
  // nobody has looked at what the studio makes. The config guidance reserves
  // full points for "core focus" and half for "occasional", and a search-engine
  // match is squarely the latter.
  //
  // Why it matters beyond one criterion: full credit would inflate EVERY
  // YouTube-sourced lead by up to 15 points against hand-researched rows, and
  // Checkpoint 1 (P11) compares approval rate PER SOURCE. A structural
  // advantage for one connector would read as that connector finding better
  // companies. A reviewer who actually watches the channel can raise it to 1.
  if (ctx.genre_hint) {
    scoringInputs.genre_fit = 0.5;
  }

  if (country) {
    scoringInputs.geography_signal = country === 'US' ? 'us' : 'non_us';
  }

  const isKnownMajor = KNOWN_MAJORS_KEYWORDS.some(k => haystack.includes(k));
  const isOversized = subscriberCount !== null && subscriberCount >= OVERSIZED_SUBSCRIBER_CEILING;
  if (isKnownMajor || isOversized) {
    scoringInputs.major_or_oversized_signal = true;
  }

  scoringInputs.has_reachable_presence = true; // a channel is itself a presence - always confirmed true

  const domain = extractDomain(description);
  const email = extractEmail(description);

  output.push({
    json: {
      segment_id: ctx.segment_id,
      name: title,
      domain: domain,
      source: 'youtube_api',
      source_url: `https://www.youtube.com/channel/${ctx.channel_id}`,
      raw: {
        channel_id: ctx.channel_id,
        matched_query: ctx.matched_query,
        subscriber_count: subscriberCount,
        video_count: stats.videoCount ? parseInt(stats.videoCount, 10) : null,
        country: country,
        description: description,
        extracted_email: email,
        scoring_inputs: scoringInputs
      }
    }
  });
});

return output;

// Node: Summarize For Source Run  |  Mode: Run Once for All Items
// This node is a PARALLEL branch off "Filter, Score, and Shape for
// Staging" - it reads the same admitted-candidate items that also flow
// to the staging_candidates insert, and collapses them into one summary
// row for source_runs. It does not run after that insert; it runs
// alongside it, on the same input.

// SHARED BY EVERY CONNECTOR (2026-08-24). `source` is read off the incoming
// items rather than hardcoded, so the same node serves YouTube, News RSS,
// X-intent, Wikidata and AICP without five near-identical copies drifting
// apart. Each connector's shaping node already stamps `source` on every row.
const items = $input.all();
const first = items.length > 0 ? items[0].json : {};
const segmentId = first.segment_id || null;
const source = first.source || 'unknown';

return [{
  json: {
    segment_id: segmentId,
    source: source,
    candidates_found: items.length,
    candidates_new: items.length, // dedupe against EXISTING entities happens later, at the promote step (P9)
    status: 'succeeded'
  }
}];
